#!/usr/bin/env node
/**
 * Generates src/styles/theme.css from @pollwise/shared/tokens so Tailwind uses the same colours,
 * type, radii and spacing as the mobile app (CLAUDE.md: never hard-code a hex value in a component).
 *
 * Run automatically before `dev` and `build`. Do not edit theme.css by hand: change
 * shared/tokens.js (which is copied from brand/tokens.js) and re-run.
 */
import { writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { colors, font, radius, space, type } from '@pollwise/shared/tokens';

const here = dirname(fileURLToPath(import.meta.url));
const OUT = join(here, '..', 'src', 'styles', 'theme.css');

/** Tailwind theme variables, one per line. */
function block(lines) {
  return lines.map((line) => `  ${line}`).join('\n');
}

const colourLines = Object.entries(colors).map(([name, hex]) => `--color-${name}: ${hex};`);

const radiusLines = Object.entries(radius).map(([name, px]) => `--radius-${name}: ${px}px;`);

const spacingLines = Object.entries(space).map(([name, px]) => `--spacing-${name}: ${px}px;`);

const typeLines = Object.entries(type).flatMap(([name, t]) => {
  const weight = `--font-weight-pw-${name}: ${t.weight};`;
  const size = `--text-pw-${name}: ${t.size}px;`;
  const line = `--text-pw-${name}--line-height: ${t.line}px;`;
  return [size, line, weight];
});

const css = `/*
 * GENERATED by admin/scripts/build-theme.js from shared/tokens.js. Do not edit by hand.
 */
@theme {
  --font-sans: ${font.webFamily};
${block(colourLines)}
${block(radiusLines)}
${block(spacingLines)}
${block(typeLines)}
}
`;

await writeFile(OUT, css, 'utf8');
console.log(`Wrote ${OUT}`);
